const lessons={
zh:[
{slug:'DIAGNOSE',nav:'6.1 诊断布局',title:'先发现问题，再选择工具',q:'CampusHub 看似“什么都有”，为什么仍然难用？',out:'布局决策始于信息关系，而不是 CSS 属性。',concept:'布局是信息结构的可视化',body:['页面布局的第一步不是写代码，而是识别信息的主次、分组与阅读顺序。一个页面即使没有溢出，也可能因为层级弱、对齐随机、间距无规律而难以理解。','我们用“现象 → 问题 → 原理 → 决策 → 结果”诊断 CampusHub。下面的分数是教学启发式指标，不是正式 Web 标准。'],points:[['层级 Hierarchy','用户先看到最重要的任务'],['邻近 Proximity','相关内容在空间上形成组'],['对齐 Alignment','共享边界建立秩序'],['留白 Whitespace','让信息关系可被看见']],code:`.page {\n  max-width: 72rem;\n  margin-inline: auto;\n  padding-inline: clamp(1rem, 4vw, 3rem);\n}`,notes:[['max-width','控制舒适阅读宽度'],['margin-inline','让容器居中'],['clamp()','让边距随空间流动']]},
{slug:'FLOW',nav:'6.2 正常流',title:'先相信文档，再打破文档',q:'没有任何布局代码时，浏览器已经做了什么？',out:'正常流是可靠阅读顺序与响应式页面的地基。',concept:'Normal Flow 是默认的布局算法',body:['块级内容自然向下排列，行内内容在可用空间中换行。这不是“没有布局”，而是一套能适应内容长度、字体和视口变化的稳健算法。','只有当视觉关系无法由自然顺序表达时，才引入 Flexbox、Grid 或定位。绝对定位会让元素脱离正常流，不应承担主要页面结构。'],points:[['源顺序 Source order','HTML 顺序表达含义'],['阅读顺序 Reading order','视觉路径与内容逻辑一致'],['内容增长 Content growth','文字变长时页面仍成立'],['增强 Enhancement','在可靠基础上增加布局']],code:`<main>\n  <h1>Campus events</h1>\n  <section>Featured events</section>\n  <aside>Popular clubs</aside>\n</main>\n\n/* Start with the document */\nmain > * + * { margin-block-start: 1.5rem; }`,notes:[['语义顺序','先写合理的 HTML 阅读顺序'],['相邻选择器','用关系定义垂直节奏'],['渐进增强','窄屏无需“重置”布局']]},
{slug:'FLEXBOX',nav:'6.3 Flexbox',title:'一维问题，用一维模型解决',q:'导航栏为什么适合 Flexbox，而活动列表未必适合？',out:'当关系主要沿一个轴发生时，选择 Flexbox。',concept:'Flexbox 管理一条轴上的分配与对齐',body:['CampusHub 顶部导航的元素只需要在横向排列、分配剩余空间并保持纵向对齐，因此它是典型的一维问题。Flexbox 的关键不是背属性，而是先确认主轴和交叉轴。','gap 把间距定义为容器规则；margin 则属于单个元素。把重复关系交给容器，组件更容易复用。'],points:[['主轴 Main axis','排列与剩余空间分配'],['交叉轴 Cross axis','各项目在另一方向对齐'],['弹性 Flexibility','项目可增长或收缩'],['换行 Wrapping','仍以每一行为一维计算']],code:`.site-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 1.5rem;\n}\n\n.nav { margin-inline-start: auto; }`,notes:[['display: flex','建立一维布局上下文'],['align-items','控制交叉轴关系'],['justify-content','分配主轴剩余空间'],['gap','把间距定义成系统规则']]},
{slug:'GRID',nav:'6.4 CSS Grid',title:'二维关系，需要共同坐标系',q:'卡片和侧栏同时需要行列对齐，该选什么？',out:'同时控制行与列时，让 Grid 建立共同坐标系。',concept:'Grid 将二维结构显式化',body:['活动卡片区既要列宽一致，又要让多行内容保持对齐；主内容与侧栏也需要明确的列关系。这类二维问题适合 Grid。','fr 表示剩余空间的比例，minmax(0, 1fr) 允许内容列真正收缩；auto-fit 与 minmax 可以让布局由内容需求决定，而不是枚举设备型号。'],points:[['轨道 Tracks','列与行构成共享坐标系'],['区域 Areas','用名称表达页面结构'],['最小约束 Minimum','保护内容可读下限'],['剩余空间 Fraction','按关系分配可用空间']],code:`.main-layout {\n  display: grid;\n  grid-template-columns: minmax(0, 1fr) 18rem;\n  gap: 2rem;\n}\n.event-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(14rem, 1fr));\n}`,notes:[['minmax(0, 1fr)','主列可收缩且占据剩余空间'],['18rem','侧栏以内容需求为约束'],['auto-fit','按可用空间自动决定列数']]},
{slug:'SYSTEM',nav:'6.5 间距系统',title:'让空间表达关系，而非填补空白',q:'为什么“差不多的间距”会让页面显得凌乱？',out:'一致的间距比例会建立节奏，并暗示内容分组。',concept:'Alignment、Proximity 与 Rhythm 共同构建秩序',body:['间距不是装饰。组内距离应小于组间距离，稳定的间距尺度让用户无需边框也能理解分组。对齐线则让不同模块共享视觉骨架。','使用少量 spacing tokens，而不是每次凭感觉输入新数值。这样既提高一致性，也让响应式调整更可控。'],points:[['4 / 8','图标与紧密元素'],['16','同组内容'],['24 / 32','模块之间'],['48 / 64','页面章节']],code:`:root {\n  --space-1: .25rem;\n  --space-2: .5rem;\n  --space-4: 1rem;\n  --space-8: 2rem;\n}\n.card { padding: var(--space-4); }\n.card-list { gap: var(--space-8); }`,notes:[['Token','有限选择带来一致节奏'],['组内 < 组间','距离本身传达关系'],['共享边界','对齐减少视觉噪声']]},
{slug:'RESPONSIVE',nav:'6.6 响应式',title:'让内容决定断点',q:'响应式是适配几种设备，还是管理连续变化？',out:'先使用流动与内在布局，只在内容关系破裂时添加断点。',concept:'Responsive Design 是关系的连续适应',body:['固定布局假设内容和屏幕不会变化；流动容器承认空间是连续变量。断点不应来自某款手机的尺寸，而应出现在内容开始拥挤、层级或可读性受损的位置。','现代组件还可以根据自身容器而非整个视口响应。同一张活动卡片放在侧栏与主区域时，可以自动选择纵向或横向形态。'],points:[['Fluid','百分比、fr 与 clamp() 连续变化'],['Intrinsic','由内容最小/最大需求参与决策'],['Breakpoint','在关系失效处改变结构'],['Container','组件根据可用容器响应']],code:`.shell { width: min(72rem, 100% - 2rem); }\n\n@media (max-width: 45rem) {\n  .main-layout { grid-template-columns: 1fr; }\n}\n\n.card-wrap { container-type: inline-size; }\n@container (min-width: 32rem) {\n  .event-card { grid-template-columns: 10rem 1fr; }\n}`,notes:[['min()','上限与流动宽度同时成立'],['45rem','内容关系破裂时切换'],['@container','组件响应自己的空间']]},
{slug:'ACCESS',nav:'6.7 最终挑战',title:'视觉重排不能破坏阅读顺序',q:'一个漂亮的布局，键盘和读屏用户也能顺利使用吗？',out:'源顺序、阅读顺序、视觉顺序与焦点顺序应保持一致。',concept:'可访问性是布局质量的一部分',body:['Grid 和 Flexbox 可以改变视觉位置，但读屏与键盘焦点通常仍遵循 DOM 顺序。如果只为视觉效果重排，界面就可能出现“眼睛看到 A，Tab 却先到 C”的冲突。','最终挑战是为 CampusHub 选择布局模型，同时守住内容层级、响应式与可访问性。好的布局不只在一张截图里成立。'],points:[['DOM','先建立有意义的源顺序'],['Visual','避免与源顺序发生冲突'],['Focus','焦点移动符合预期路径'],['Zoom','放大与文字增长时仍可用']],code:`/* Prefer source order over visual reordering */\n.main-layout {\n  display: grid;\n  grid-template-areas: "main aside";\n}\n\n@media (max-width: 45rem) {\n  .main-layout { grid-template-areas: "main" "aside"; }\n}\n\n:focus-visible { outline: 3px solid #0b7a66; }`,notes:[['grid-template-areas','视觉结构仍遵循 DOM 逻辑'],['避免 order: -1','不制造视觉/焦点冲突'],[':focus-visible','让键盘位置清晰可见']]}
],
en:[]};
lessons.en=[
['DIAGNOSE','6.1 Diagnose layout','Find the problem before choosing a tool','CampusHub seems to have everything. Why is it still hard to use?','Layout decisions begin with information relationships, not CSS properties.','Layout visualizes information structure',['The first step is not writing CSS. It is identifying hierarchy, grouping, and reading order. A page can fit the viewport and still be hard to understand when hierarchy is weak, alignment is arbitrary, and spacing has no pattern.','We diagnose CampusHub through “symptom → problem → principle → decision → result.” The scores below are teaching heuristics, not a formal Web standard.'],[['Hierarchy','The primary task should be seen first'],['Proximity','Related content forms a spatial group'],['Alignment','Shared edges create order'],['Whitespace','Makes relationships perceptible']]],
['FLOW','6.2 Normal flow','Trust the document before breaking it','What is the browser already doing before we add layout code?','Normal flow is the foundation of reliable reading order and responsive pages.','Normal Flow is the default layout algorithm',['Blocks stack vertically and inline content wraps within available space. This is not “no layout”; it is a robust algorithm that adapts to content length, type size, and viewport changes.','Introduce Flexbox, Grid, or positioning only when the visual relationship cannot be expressed by natural order. Absolute positioning removes elements from normal flow and should not carry the main page structure.'],[['Source order','HTML order expresses meaning'],['Reading order','The visual path matches content logic'],['Content growth','The page survives longer text'],['Enhancement','Add layout over a reliable base']]],
['FLEXBOX','6.3 Flexbox','Solve one-dimensional problems with a one-dimensional model','Why does Flexbox suit navigation, but not every card collection?','Choose Flexbox when relationships mainly happen along one axis.','Flexbox manages distribution and alignment on one axis',['CampusHub navigation only needs horizontal arrangement, leftover-space distribution, and vertical alignment. That makes it a one-dimensional problem. The key is not memorizing properties, but identifying the main and cross axes first.','gap defines spacing as a container rule; margin belongs to an individual item. Giving repeated relationships to the container makes components easier to reuse.'],[['Main axis','Arrangement and free-space distribution'],['Cross axis','Item alignment in the other direction'],['Flexibility','Items may grow or shrink'],['Wrapping','Each line is still calculated in one dimension']]],
['GRID','6.4 CSS Grid','Two-dimensional relationships need shared coordinates','Cards and a sidebar need row and column alignment. What should we choose?','When rows and columns matter together, use Grid as the shared coordinate system.','Grid makes two-dimensional structure explicit',['The event card area needs consistent columns and alignment across multiple rows; the content and sidebar also need an explicit column relationship. These are two-dimensional problems.','fr represents a share of remaining space, while minmax(0, 1fr) lets a content column truly shrink. auto-fit with minmax lets content needs drive the layout instead of enumerating devices.'],[['Tracks','Rows and columns create coordinates'],['Areas','Names communicate page structure'],['Minimum','Protects the readable lower bound'],['Fraction','Distributes available space relationally']]],
['SYSTEM','6.5 Spacing system','Use space to express relationships, not fill emptiness','Why does “roughly similar spacing” still feel disorderly?','A consistent spacing ratio creates rhythm and reveals grouping.','Alignment, Proximity, and Rhythm create order together',['Spacing is not decoration. Distances within a group should be smaller than distances between groups. A stable scale lets users understand grouping without relying on borders. Alignment gives separate modules a common visual skeleton.','Use a small set of spacing tokens instead of inventing a new value each time. Consistency improves, and responsive adjustments become easier to control.'],[['4 / 8','Icons and tightly related items'],['16','Content within a group'],['24 / 32','Between modules'],['48 / 64','Between page sections']]],
['RESPONSIVE','6.6 Responsive','Let content determine the breakpoint','Is responsiveness about a few devices, or continuous change?','Use fluid and intrinsic layout first; add a breakpoint only when a relationship breaks.','Responsive Design continuously adapts relationships',['A fixed layout assumes content and screens never change; a fluid container accepts that space is continuous. A breakpoint should not come from a phone model, but from the point where content becomes crowded or hierarchy and readability suffer.','Modern components can respond to their own container rather than the whole viewport. The same event card can become vertical in a sidebar and horizontal in the main region.'],[['Fluid','Percentages, fr, and clamp() change continuously'],['Intrinsic','Content minima and maxima guide decisions'],['Breakpoint','Structure changes when a relationship fails'],['Container','A component responds to its own space']]],
['ACCESS','6.7 Final challenge','Visual rearrangement must not break reading order','Can keyboard and screen-reader users navigate a beautiful layout?','Source, reading, visual, and focus order should remain consistent.','Accessibility is part of layout quality',['Grid and Flexbox can change visual position, but screen readers and keyboard focus usually follow DOM order. Visual-only rearrangement can create a conflict where the eye sees A first but Tab reaches C first.','The final challenge is to choose a model for CampusHub while preserving hierarchy, responsiveness, and accessibility. Good layout must work beyond a single screenshot.'],[['DOM','Begin with meaningful source order'],['Visual','Avoid conflict with source order'],['Focus','Focus follows the expected path'],['Zoom','The page survives enlargement and text growth']]]
].map((x,i)=>({slug:x[0],nav:x[1],title:x[2],q:x[3],out:x[4],concept:x[5],body:x[6],points:x[7],code:lessons.zh[i].code,notes:lessons.zh[i].notes.map((n,j)=>[n[0],x[7][j]?.[1]||n[1]])}));

const ui={zh:{course:'页面布局',xray:'布局透视',title:'从信息结构到响应式界面',lead:'好的布局不是把元素放到正确的位置，而是在内容、屏幕和用户条件改变时，仍保持清晰的视觉关系。',progress:'课程进度',outcome:'本节结论',explain:'讲解',code:'关键代码',demo:'动态演示',prev:'上一节',next:'下一节',copy:'复制代码',copied:'已复制',run:'在演示中运行',demoTitle:'动手改变布局',demoHint:'调整控制项，观察空间关系如何改变。'},en:{course:'PAGE LAYOUT',xray:'Layout X-Ray',title:'From Information Structure to Responsive Interfaces',lead:'Good layout is not merely placing elements in the right position. It preserves clear visual relationships as content, screens, and user contexts change.',progress:'Course progress',outcome:'Takeaway',explain:'Explanation',code:'Key code',demo:'Live demo',prev:'Previous',next:'Next',copy:'Copy code',copied:'Copied',run:'Run in demo',demoTitle:'Change the layout',demoHint:'Adjust the controls and observe how spatial relationships change.'}};
let lang=localStorage.getItem('layout-lang')||'zh',current=0,tab='explain';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
function renderNav(){const nav=$('#lessonNav');nav.innerHTML=lessons[lang].map((l,i)=>`<button class="lesson-nav ${i===current?'active':''}" data-lesson="${i}"><b>0${i+1}</b><span>${l.nav.replace(/^6\.\d\s*/,'')}</span></button>`).join('');$$('[data-lesson]').forEach(b=>b.onclick=()=>{current=+b.dataset.lesson;tab='explain';render()})}
function render(){const t=ui[lang],l=lessons[lang][current];document.documentElement.lang=lang==='zh'?'zh-CN':'en';$$('[data-t]').forEach(el=>el.textContent=t[el.dataset.t]);$$('[data-lang]').forEach(b=>b.classList.toggle('active',b.dataset.lang===lang));$('#caseCount').textContent=`CASE 0${current+1} / 07`;$('#caseLabel').textContent=`CASE 0${current+1} · ${l.slug}`;$('#lessonTitle').textContent=l.title;$('#lessonQuestion').textContent=l.q;$('#lessonOutcome').textContent=l.out;$('#progressText').textContent=`${Math.round((current+1)/7*100)}%`;$('#progressBar').style.width=`${(current+1)/7*100}%`;$('#footerCase').textContent=`${current+1} / 7`;$('#prevBtn').disabled=current===0;$('#nextBtn').disabled=current===6;$$('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));renderNav();renderPanel()}
function renderPanel(){const l=lessons[lang][current],t=ui[lang];if(tab==='explain'){$('#panel').innerHTML=`<div class="prose"><p class="eyebrow">${l.concept}</p><h3>${l.q}</h3>${l.body.map(x=>`<p>${x}</p>`).join('')}<div class="logic"><span>${lang==='zh'?'现象':'Symptom'}</span><span>${lang==='zh'?'问题':'Problem'}</span><span>${lang==='zh'?'原理':'Principle'}</span><span>${lang==='zh'?'决策':'Decision'}</span><span>${lang==='zh'?'结果':'Result'}</span></div><div class="principles">${l.points.map(p=>`<article><b>${p[0]}</b><small>${p[1]}</small></article>`).join('')}</div></div>`}else if(tab==='code'){$('#panel').innerHTML=`<div class="code-layout"><div><div class="code-box"><button class="copy">${t.copy}</button><pre><code>${escapeHtml(l.code)}</code></pre></div><button class="run-btn">▶ ${t.run}</button></div><div class="annotations">${l.notes.map(n=>`<div><b>${n[0]}</b><small>${n[1]}</small></div>`).join('')}</div></div>`;$('.copy').onclick=async e=>{await navigator.clipboard.writeText(l.code);e.target.textContent=t.copied};$('.run-btn').onclick=()=>{tab='demo';render()}}else renderDemo(l,t)}
function escapeHtml(s){return s.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;')}
function campus(){let s=$('#campusTemplate').innerHTML;if(lang==='zh')s=s.replace('Discover　Clubs　Events','发现　社团　活动').replace('Sign in','登录').replace('THIS WEEK','本周精选').replace('Make campus feel smaller.','让校园因连接而更亲近。').replace('Design Night','设计之夜').replace('Studio A','A 工作室').replace('Open Stage','开放舞台').replace('South Lawn','南草坪').replace('Green Market','绿色市集').replace('Library Walk','图书馆步道').replace('Popular now','热门活动').replace('Film Society','电影社').replace('Night Run','夜跑');return s}
function demoWrap(body){return `<div class="demo-head"><div><h3>${ui[lang].demoTitle}</h3><p>${ui[lang].demoHint}</p></div></div>${body}`}
function renderDemo(l,t){let html='';if(current===0)html=demoWrap(`<div class="metrics">${['Hierarchy 42','Alignment 51','Spacing 35','Responsive 20','Access 68'].map(x=>{let [a,b]=x.split(' ');return `<div class="metric"><span>${a}</span><b>${b}</b><i style="width:${b}%"></i></div>`}).join('')}</div><div class="diagnosis"><div class="issue-list"><button>⚠ ${lang==='zh'?'内容宽度固定':'Fixed content width'}</button><button>⚠ ${lang==='zh'?'层级不清':'Weak hierarchy'}</button><button>⚠ ${lang==='zh'?'间距不一致':'Inconsistent spacing'}</button><button>⚠ ${lang==='zh'?'侧栏破坏阅读顺序':'Sidebar breaks reading order'}</button></div><div class="bad">${campus()}</div></div>`);if(current===1)html=demoWrap(`<div class="controls"><button id="flowToggle">${lang==='zh'?'脱离正常流':'Break normal flow'}</button></div><div style="position:relative;margin-top:18px" class="flow-stack" id="flowDemo"><header>1 · Header</header><article>2 · Main content</article><aside>3 · Supporting content</aside><footer>4 · Footer</footer></div>`);if(current===2)html=demoWrap(`<div class="controls"><button data-flex="row" class="active">Row</button><button data-flex="column">Column</button><button id="justify">${lang==='zh'?'居中主轴':'Center main axis'}</button></div><div class="axis-demo" id="axisDemo"><article>A</article><article>B</article><article>C</article></div>`);if(current===3)html=demoWrap(`<div class="controls"><span>${lang==='zh'?'列数':'Columns'}</span><button data-cols="1">1</button><button data-cols="2">2</button><button data-cols="3" class="active">3</button><button data-cols="4">4</button></div><div class="grid-demo" id="gridDemo">${[1,2,3,4,5,6].map(n=>`<article>Event ${n}</article>`).join('')}</div>`);if(current===4)html=demoWrap(`<div class="controls"><button data-gap="g4">4px</button><button data-gap="g16" class="active">16px</button><button data-gap="g32">32px</button></div><div class="spacing-demo g16" id="spacingDemo"><article>Title<br><small>Metadata</small></article><article>Title<br><small>Metadata</small></article><article>Title<br><small>Metadata</small></article></div>`);if(current===5)html=demoWrap(`<div class="controls"><label>Viewport: <b id="vpLabel">920px</b></label><input class="range" id="viewport" type="range" min="320" max="1100" value="920"></div>${campus()}<pre class="responsiveCode"><code>.main { grid-template-columns: minmax(0, 1fr) 18rem; }</code></pre>`);if(current===6)html=demoWrap(`<div class="decision"><p>${lang==='zh'?'你需要排列什么？':'What do you need to arrange?'}</p><div class="decision-stage"><button class="choice" data-answer="one">${lang==='zh'?'一个方向':'One direction'}</button><button class="choice" data-answer="two">${lang==='zh'?'两个方向':'Two directions'}</button><button class="choice" data-answer="read">${lang==='zh'?'自然阅读内容':'Natural reading content'}</button></div><div class="recommend" id="recommend">${lang==='zh'?'选择一种关系，查看建议':'Choose a relationship to see a recommendation'}</div><div class="a11y-list"><div class="a11y-row"><b>1</b>Header</div><div class="a11y-row"><b>2</b>Main content</div><div class="a11y-row"><b>3</b>Supporting content</div></div></div>`);$('#panel').innerHTML=html;bindDemo()}
function bindDemo(){if(current===0)$$('.issue-list button').forEach((b,i)=>b.onclick=()=>{b.classList.add('found');const vals=[62,67,58,43,72];$$('.metric b').forEach((x,j)=>{x.textContent=vals[j];x.nextElementSibling.style.width=vals[j]+'%'})});if(current===1)$('#flowToggle').onclick=e=>{$('#flowDemo').classList.toggle('absolute');e.target.classList.toggle('active')};if(current===2){$$('[data-flex]').forEach(b=>b.onclick=()=>{$('#axisDemo').classList.toggle('column',b.dataset.flex==='column');$$('[data-flex]').forEach(x=>x.classList.toggle('active',x===b))});$('#justify').onclick=e=>{$('#axisDemo').classList.toggle('center');e.target.classList.toggle('active')}}if(current===3)$$('[data-cols]').forEach(b=>b.onclick=()=>{$('#gridDemo').style.gridTemplateColumns=`repeat(${b.dataset.cols},1fr)`;$$('[data-cols]').forEach(x=>x.classList.toggle('active',x===b))});if(current===4)$$('[data-gap]').forEach(b=>b.onclick=()=>{const d=$('#spacingDemo');d.className=`spacing-demo ${b.dataset.gap}`;$$('[data-gap]').forEach(x=>x.classList.toggle('active',x===b))});if(current===5){const r=$('#viewport'),ui=$('.campus-ui'),code=$('.responsiveCode code');const update=()=>{const w=+r.value;$('#vpLabel').textContent=w+'px';ui.style.width=Math.min(w,ui.parentElement.clientWidth)+'px';ui.querySelector('.campus-grid').style.gridTemplateColumns=w<720?'1fr':'minmax(0,1fr) 180px';ui.querySelector('.event-grid').style.gridTemplateColumns=w<520?'1fr':w<850?'repeat(2,1fr)':'repeat(3,1fr)';code.textContent=w<720?'@media (max-width: 720px) { .main { grid-template-columns: 1fr; } }':'.main { grid-template-columns: minmax(0, 1fr) 18rem; }'};r.oninput=update;update()}if(current===6)$$('[data-answer]').forEach(b=>b.onclick=()=>{const ans={one:['Flexbox','一维关系：用主轴与交叉轴管理分配和对齐。','One-dimensional relationship: manage distribution and alignment with main and cross axes.'],two:['CSS Grid','二维关系：用共享行列坐标系对齐内容。','Two-dimensional relationship: align content on shared rows and columns.'],read:['Normal Flow','让源顺序成为布局基础，再渐进增强。','Let source order form the layout foundation, then enhance progressively.']}[b.dataset.answer];$('#recommend').innerHTML=`<b>✓ ${ans[0]}</b><br>${lang==='zh'?ans[1]:ans[2]}`;$$('.choice').forEach(x=>x.classList.toggle('active',x===b))})}
$$('[data-lang]').forEach(b=>b.onclick=()=>{lang=b.dataset.lang;localStorage.setItem('layout-lang',lang);render()});$$('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});$('#prevBtn').onclick=()=>{if(current){current--;tab='explain';render();scrollTo({top:0,behavior:'smooth'})}};$('#nextBtn').onclick=()=>{if(current<6){current++;tab='explain';render();scrollTo({top:0,behavior:'smooth'})}};$('#xrayBtn').onclick=e=>{document.body.classList.toggle('xray');e.currentTarget.setAttribute('aria-pressed',document.body.classList.contains('xray'))};render();
